// ─── Inside route.ts ──────────────────────────────────────────────────────────
import jwt from "jsonwebtoken";
import jwksClient from "jwks-rsa";
import { encode } from "next-auth/jwt";
import { prisma } from "@/lib/prisma";
import { createNewSession } from "@/lib/auth"; // Import the function we just exported

const tenantId = process.env.MICROSOFT_ENTRA_TENANT_ID!;
const clientId = process.env.MICROSOFT_ENTRA_CLIENT_ID!;

const AUTH_JWT_SALT = "authjs.session-token";

const client = jwksClient({
  jwksUri: `https://login.microsoftonline.com/${tenantId}/discovery/v2.0/keys`,
});

function getKey(header: any, callback: any) {
  client.getSigningKey(header.kid, (err, key) => {
    const signingKey = key?.getPublicKey();
    callback(null, signingKey);
  });
}

export async function POST(req: Request) {
  const { token } = await req.json();
  const authSecret = process.env.AUTH_SECRET;

  if (!token) {
    return Response.json({ error: "Missing token" }, { status: 400 });
  }

  if (!authSecret) {
    return Response.json({ error: "Missing AUTH_SECRET" }, { status: 500 });
  }

  try {
    // 1. VERIFY MICROSOFT TOKEN
    const decoded: any = await new Promise((resolve, reject) => {
      jwt.verify(
        token,
        getKey,
        {
          audience: clientId,
          issuer: `https://login.microsoftonline.com/${tenantId}/v2.0`,
        },
        (err, decoded) => {
          if (err) reject(err);
          else resolve(decoded);
        }
      );
    });

    const email = decoded.email || decoded.preferred_username;
    const name = decoded.name;

    // 2. FIND OR CREATE USER
    const user = await prisma.appUsers.upsert({
      where: { email },
      update: {
        displayName: name,
      },
      create: {
        email,
        username: email.split("@")[0],
        displayName: name,
        passwordHash: "", 
        isActive: true,
        isEntraUser: true,
      },
    });

    // 3. CREATE THE DATABASE SESSION FOR THIS MOBILE DEVICE
    const sessionDetails = await createNewSession(user.id);

    // 4. MINT THE ENCODED TOKEN CONTAINING TRACKING DETAILS
    const appToken = await encode({
      secret: authSecret,
      salt: AUTH_JWT_SALT,
      token: {
        sub: user.id,
        email: user.email,
        username: user.username,
        role: user.role,
        isActive: user.isActive,
        loginMethod: "entra",
        
        // This links the token to your auth.ts lifecycle checks
        sessionId: sessionDetails.sessionId,
        cookieVersion: sessionDetails.cookieVersion,
        lastVerified: sessionDetails.lastVerified,
      },
    });

    return Response.json({
      token: appToken,
      user,
    });
    
  } catch (error) {
    console.error("[route.ts] Auth pipeline failed:", error);
    return Response.json({ error: "Authentication failed" }, { status: 401 });
  }
}

// app/api/azure/route.ts
// Proxies requests to Azure Resource Manager (management.azure.com).
// Usage: GET /api/azure?resource=<key>

import { getGraphToken } from "@/lib/AzureHelper";
import { NextRequest } from "next/server";

const ARM_BASE = "https://management.azure.com";
const SUB_ID = process.env.AZURE_SUBSCRIPTION_ID;

// ARM API versions per resource type
const API_VERSIONS: Record<string, string> = {
  subscriptions:    "2022-12-01",
  resourceGroups:   "2021-04-01",
  virtualMachines:  "2024-03-01",
  storageAccounts:  "2023-01-01",
  roleAssignments:  "2022-04-01",
};

// ARM URL builder per resource key
function buildUrl(resource: string): string | null {
  switch (resource) {
    case "subscriptions":
      // List all subscriptions the service principal can see
      return `${ARM_BASE}/subscriptions?api-version=${API_VERSIONS.subscriptions}`;

    case "resourceGroups":
      return `${ARM_BASE}/subscriptions/${SUB_ID}/resourcegroups?api-version=${API_VERSIONS.resourceGroups}`;

    case "virtualMachines":
      // Subscription-wide VM list — includes all resource groups
      return `${ARM_BASE}/subscriptions/${SUB_ID}/providers/Microsoft.Compute/virtualMachines?api-version=${API_VERSIONS.virtualMachines}`;

    case "storageAccounts":
      return `${ARM_BASE}/subscriptions/${SUB_ID}/providers/Microsoft.Storage/storageAccounts?api-version=${API_VERSIONS.storageAccounts}`;

    case "roleAssignments":
      return `${ARM_BASE}/subscriptions/${SUB_ID}/providers/Microsoft.Authorization/roleAssignments?api-version=${API_VERSIONS.roleAssignments}`;

    default:
      return null;
  }
}

export async function GET(request: NextRequest) {
  const { searchParams } = new URL(request.url);
  const resource = searchParams.get("resource") ?? "";

  const url = buildUrl(resource);
  if (!url) {
    return Response.json(
      { error: "Unknown resource", resource },
      { status: 400 }
    );
  }

  if (!SUB_ID && resource !== "subscriptions") {
    return Response.json(
      { error: "AZURE_SUBSCRIPTION_ID is not set" },
      { status: 500 }
    );
  }

  try {
    const tokenData = await getGraphToken();

    console.log(`➡️  ARM request [${resource}]: ${url}`);

    const res = await fetch(url, {
      method: "GET",
      headers: {
        Authorization: `Bearer ${tokenData.access_token}`,
        "Content-Type": "application/json",
      },
    });

    console.log(`📡 ARM status [${resource}]:`, res.status);
    const text = await res.text();

    if (!res.ok) {
      console.error(`❌ ARM error [${resource}]:`, text);
      return Response.json(
        {
          error: "Azure Resource Manager returned an error",
          status: res.status,
          details: text,
        },
        { status: res.status }
      );
    }

    return Response.json(JSON.parse(text));
  } catch (error: any) {
    console.error(`❌ Unexpected error [${resource}]:`, error);
    return Response.json(
      {
        error: "Failed to fetch from Azure Resource Manager",
        message: error.message,
      },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from "next/server";
import { auth } from "@/lib/auth";
import { prisma } from "@/lib/prisma";
import { getToken } from "next-auth/jwt";
import { resolveTicketingActor } from "@/lib/ticketing-auth";

export const runtime = "nodejs";

export async function POST(request: NextRequest) {
  try {
    const actor = await resolveTicketingActor(request);

      if (!actor?.userId) {
        return createError("Unauthorized", 401);
      }

    const userId = actor.userId;

    const body = await request.json();

    const {
      token: fcmToken,
      platform,
      deviceVersion,
      deviceName,
      deviceModelName,
      deviceBrand,
    } = body as {
      token?: string;
      platform?: string;
      deviceVersion?: string;
      deviceName?: string;
      deviceModelName?: string;
      deviceBrand?: string;
    };

    if (!fcmToken || !platform) {
      return NextResponse.json(
        { error: "Missing token or platform" },
        { status: 400 }
      );
    }

    const device = await prisma.deviceToken.upsert({
      where: {
        token: fcmToken,
      },
      update: {
        userId,
        platform: platform.toLowerCase(),

        deviceVersion,
        deviceName,
        deviceModelName,
        deviceBrand,

        updatedAt: new Date(),
      },
      create: {
        token: fcmToken,
        userId,
        platform: platform.toLowerCase(),

        deviceVersion,
        deviceName,
        deviceModelName,
        deviceBrand,
      },
    });

    return NextResponse.json({
      success: true,
      deviceId: device.id,
    });
  } catch (error) {
    console.error("DEVICE_REGISTER_ERROR:", error);

    return NextResponse.json(
      { error: "Failed to register device" },
      { status: 500 }
    );
  }
}

function createError(message: string, status: number) {
  return NextResponse.json({ error: message }, { status });
}

// app/api/entra/route.ts
// Proxies requests to Microsoft Graph API.
// Usage: GET /api/entra?resource=<key>[&top=<n>]

import { getGraphToken } from "@/lib/EntraHelper";
import { NextRequest } from "next/server";

const GRAPH_BASE = "https://graph.microsoft.com/v1.0";

// Map of allowed resource keys → Graph API path segments
const RESOURCE_MAP: Record<string, string> = {
  "users":                                 "users",
  "groups":                                "groups",
  "devices":                               "devices",
  "applications":                          "applications",
  "auditLogs/signIns":                     "auditLogs/signIns",
  "identity/conditionalAccess/policies":   "identity/conditionalAccess/policies",
};

// Lean $select fields per resource to avoid over-fetching
const SELECT_MAP: Record<string, string> = {
  users: [
    "id", "displayName", "userPrincipalName", "accountEnabled",
    "userType", "jobTitle", "department", "createdDateTime",
    "lastPasswordChangeDateTime", "assignedLicenses",
    "strongAuthenticationMethods", "isMfaRegistered",
  ].join(","),

  groups: [
    "id", "displayName", "description", "securityEnabled",
    "mailEnabled", "groupTypes", "createdDateTime",
    "membershipRule", "membershipRuleProcessingState",
  ].join(","),

  devices: [
    "id", "displayName", "operatingSystem", "operatingSystemVersion",
    "trustType", "isCompliant", "isManaged",
    "approximateLastSignInDateTime", "registrationDateTime",
    "deviceId", "manufacturer", "model",
  ].join(","),

  applications: [
    "id", "appId", "displayName", "signInAudience",
    "createdDateTime", "passwordCredentials", "keyCredentials",
    "web", "spa", "requiredResourceAccess",
  ].join(","),
};

export async function GET(request: NextRequest) {
  const { searchParams } = new URL(request.url);
  const resource = searchParams.get("resource") ?? "";
  const top = searchParams.get("top") ?? "100";

  const graphPath = RESOURCE_MAP[resource];
  if (!graphPath) {
    return Response.json(
      { error: "Unknown resource", resource },
      { status: 400 }
    );
  }

  try {
    const tokenData = await getGraphToken();

    const params = new URLSearchParams({ $top: top });

    const select = SELECT_MAP[resource];
    if (select) params.set("$select", select);

    // Sign-in logs: last 24h only, newest first
    if (resource === "auditLogs/signIns") {
      const since = new Date(Date.now() - 24 * 60 * 60 * 1000).toISOString();
      params.set("$filter", `createdDateTime ge ${since}`);
      params.set("$orderby", "createdDateTime desc");
    }

    const url = `${GRAPH_BASE}/${graphPath}?${params.toString()}`;
    console.log(`➡️  Graph request [${resource}]: ${url}`);

    const res = await fetch(url, {
      method: "GET",
      headers: {
        Authorization: `Bearer ${tokenData.access_token}`,
        "Content-Type": "application/json",
        ConsistencyLevel: "eventual", // required for some $filter and $count queries
      },
    });

    console.log(`📡 Graph status [${resource}]:`, res.status);
    const text = await res.text();

    if (!res.ok) {
      console.error(`❌ Graph error [${resource}]:`, text);
      return Response.json(
        {
          error: "Microsoft Graph returned an error",
          status: res.status,
          details: text,
        },
        { status: res.status }
      );
    }

    return Response.json(JSON.parse(text));
  } catch (error: any) {
    console.error(`❌ Unexpected error [${resource}]:`, error);
    return Response.json(
      {
        error: "Failed to fetch from Microsoft Graph",
        message: error.message,
      },
      { status: 500 }
    );
  }
}

import { NextResponse } from "next/server";
import { prisma } from "@/lib/prisma";
import { encrypt } from "@/lib/mailboxPassword";
import { ImapFlow } from "imapflow";
import nodemailer from "nodemailer"
import { resolveTicketingActor } from "@/lib/ticketing-auth";

function wait(ms: number) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

function parseEmailAddress(email: string) {
  const [local_part, domain] = email.split("@");
  if (!local_part || !domain) {
    return null;
  }
  return { local_part, domain };
}

export async function POST(req: Request) {
  const actor = await resolveTicketingActor(req);

  if (!actor?.userId) {
    return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
  }

  const userId = actor.userId;
  const name = `user-${userId}`;
  const { email, password } = await req.json();
  const mailboxApi = process.env.MAILBOX_API;
  const mailcowApiToken = process.env.MAILCOW_API_TOKEN;
  const imapHost = process.env.IMAP_HOST;

  if (!email || !password) {
    return NextResponse.json(
      { error: "Missing email or password" },
      { status: 400 }
    );
  }

  if (!mailboxApi || !mailcowApiToken || !imapHost) {
    return NextResponse.json(
      { error: "Mailbox service is not configured" },
      { status: 500 }
    );
  }

  const parsedEmail = parseEmailAddress(email);
  if (!parsedEmail) {
    return NextResponse.json(
      { error: "Invalid email format" },
      { status: 400 }
    );
  }

  // prevent duplicates
  const existing = await prisma.userMailbox.findFirst({
    where: { userId, email },
  });

  if (existing) {
    return NextResponse.json(
      { error: "Mailbox already exists" },
      { status: 409 }
    );
  }

  /**
   * 1. CREATE mailbox on mail server (MISSING IN YOUR CURRENT CODE)
   */
  try {
    const mailcowResponse = await fetch(`${mailboxApi}`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "x-api-key": mailcowApiToken,
      },
      body: JSON.stringify({
        local_part: parsedEmail.local_part,
        domain: parsedEmail.domain,
        name: name,
        quota: 1000, // default to 1000MB if not set
        password: password,
        password2: password,
        active: "1",
        force_pw_update: "1",
        tls_enforce_in: "1",
        tls_enforce_out: "1",
      }),
    });

    const rawBody = await mailcowResponse.text();
    let parsedBody: unknown = rawBody;

    try {
      parsedBody = rawBody ? JSON.parse(rawBody) : null;
    } catch {
      // Keep raw text body for troubleshooting non-JSON API responses.
    }

    const mailcowHasAppError = Array.isArray(parsedBody)
      ? parsedBody.some((item: any) => {
          const type = String(item?.type ?? "").toLowerCase();
          return type === "error" || type === "danger";
        })
      : false;

    if (!mailcowResponse.ok || mailcowHasAppError) {
      return NextResponse.json(
        {
          error: "Failed to create mailbox on mail server",
          status: mailcowResponse.status,
          mailcowResponse: parsedBody,
        },
        { status: 502 }
      );
    }
  } catch (err) {
    return NextResponse.json(
      { error: "Failed to create mailbox on mail server", errorDetails: (err as Error).message },
      { status: 500 }
    );
  }

  /**
   * 2. VERIFY IMAP (optional safety check)
   */
  try {
    let connected = false;

    for (let attempt = 1; attempt <= 3; attempt++) {
      const client = new ImapFlow({
        host: imapHost,
        port: 993,
        secure: true,
        auth: { user: email, pass: password },
        logger: false,
      });

      try {
        await client.connect();
        await client.logout();
        connected = true;
        break;
      } catch {
        if (attempt < 3) {
          await wait(1500);
        }
      }
    }

    if (!connected) {
      return NextResponse.json(
        { error: "Mailbox created but IMAP login failed" },
        { status: 502 }
      );
    }
  } catch (err) {
    return NextResponse.json(
      { error: "Mailbox created but IMAP login failed", errorDetails: (err as Error).message },
      { status: 502 }
    );
  }

  /**
   * 3. STORE in DB
   */
  const mailbox = await prisma.userMailbox.create({
    data: {
      userId,
      email,
      encryptedPassword: encrypt(password),
    },
  });

  const transporter = nodemailer.createTransport({
        host: process.env.SMTP_HOST!, 
        port: 465, 
        secure: true, 
        auth: {
          user: process.env.SYSTEM_SMTP_USER!,
          pass: process.env.SYSTEM_SMTP_PASS!,
        },
      });

  const senderHeader = `"Fortmont Identity Services" <${process.env.SYSTEM_SMTP_USER!}>`;

    // 5. Send the email via SMTP
  const info = await transporter.sendMail({
      from: senderHeader,
      to: mailbox.email,
      subject: "Welcome to Fortmont!",
      text: `You mailbox has been successfully created for your Fortmont account, ${mailbox.email}!`
      
    });

  // Send invitation email
  

  return NextResponse.json({
    success: true,
    mailbox: {
      id: mailbox.id,
      email: mailbox.email,
    },
  });
}

import { NextResponse } from "next/server";
import { prisma } from "@/lib/prisma";
import { decrypt } from "@/lib/mailboxPassword";
import { ImapFlow } from "imapflow";
import { simpleParser } from "mailparser";
import { resolveTicketingActor } from "@/lib/ticketing-auth";

export async function GET(request: Request) {
  try {
    const actor = await resolveTicketingActor(request);

    if (!actor?.userId) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    const userId = actor.userId;

    // 2. Get mailbox
    const mailbox = await prisma.userMailbox.findFirst({
      where: { userId },
    });

    if (!mailbox) {
      return NextResponse.json(
        { error: "No mailbox linked" },
        { status: 404 }
      );
    }

    const password = decrypt(mailbox.encryptedPassword);

    // 3. IMAP client
    const client = new ImapFlow({
      host: process.env.IMAP_HOST!,
      port: 993,
      secure: true,
      auth: {
        user: mailbox.email,
        pass: password,
      },
      logger: false,
    });

    await client.connect();
    await client.mailboxOpen("INBOX");

    // 4. Ensure mailbox is valid (fix for TS + runtime safety)
    if (!client.mailbox) {
      throw new Error("Failed to open mailbox");
    }

    const total = client.mailbox.exists;

    // 5. Get last 50 messages safely
    const start = Math.max(1, total - 49);
    const range = `${start}:*`;

    const messages: any[] = [];

    for await (const msg of client.fetch(range, {
      uid: true,
      envelope: true,
      flags: true,
      internalDate: true,
      source: true,
    })) {
      messages.push(msg);
    }

    // 6. Newest first (manual reverse fix)
    messages.reverse();

    // 7. Parse emails
    const emails = [];

    for (const msg of messages) {
      let parsed = null;

      if (msg.source) {
        try {
          parsed = await simpleParser(msg.source);
        } catch {
          // Intentionally suppress per-message parse logs to avoid mailbox item leakage.
        }
      }

      emails.push({
        uid: msg.uid,
        subject: msg.envelope?.subject ?? "(no subject)",
        from: msg.envelope?.from?.[0]?.address ?? "",
        date: msg.internalDate,
        flags: msg.flags,
        body: {
          text: parsed?.text ?? "",
          html: parsed?.html ?? parsed?.textAsHtml ?? "",
        },
      });
    }

    // 8. Cleanup
    await client.logout();

    // 9. Response
    return NextResponse.json({
      mailbox: mailbox.email,
      count: emails.length,
      emails,
    });
  } catch (err) {
    if (process.env.NODE_ENV === "development") {
      console.error("EMAIL_INBOX_ERROR", err);
    }
    console.error("EMAIL_INBOX_ERROR");

    return NextResponse.json(
      { error: "Failed to fetch emails" },
      { status: 500 }
    );
  }
}

import { NextResponse } from "next/server";
import { prisma } from "@/lib/prisma";
import { decrypt } from "@/lib/mailboxPassword";
import { ImapFlow } from "imapflow";
import { simpleParser } from "mailparser";
import { resolveTicketingActor } from "@/lib/ticketing-auth";

export async function GET(request: Request) {
  try {
    const actor = await resolveTicketingActor(request);

    if (!actor?.userId) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    const userId = actor.userId;

    // 2. Get mailbox configuration
    const mailbox = await prisma.userMailbox.findFirst({
      where: { userId },
    });

    if (!mailbox) {
      return NextResponse.json(
        { error: "No mailbox linked" },
        { status: 404 }
      );
    }

    const password = decrypt(mailbox.encryptedPassword);

    // 3. Initialize IMAP client
    const client = new ImapFlow({
      host: process.env.IMAP_HOST!,
      port: 993,
      secure: true,
      auth: {
        user: mailbox.email,
        pass: password,
      },
    });

    await client.connect();
    

    // 4. Dynamically find the "Sent" folder path using special use attributes
    const list = await client.list();
    const sentFolder = list.find(folder => folder.specialUse === "\\Sent");
    
    // Fallback to common names if the server doesn't explicitly flag the specialUse attribute
    const sentFolderName = sentFolder?.path || "Sent"; 

    // 5. Open the Sent folder
    await client.mailboxOpen(sentFolderName);

    if (!client.mailbox) {
      throw new Error(`Failed to open folder: ${sentFolderName}`);
    }

    const total = client.mailbox.exists;

    // 6. Get the last 50 sent messages safely
    const start = Math.max(1, total - 49);
    const range = `${start}:*`;

    const messages: any[] = [];

    for await (const msg of client.fetch(range, {
      uid: true,
      envelope: true,
      flags: true,
      internalDate: true,
      source: true,
    })) {
      messages.push(msg);
    }

    // 7. Sort newest first
    messages.reverse();

    // 8. Parse sent emails
    const emails = [];

    for (const msg of messages) {
      let parsed = null;

      if (msg.source) {
        try {
          parsed = await simpleParser(msg.source);
        } catch (err) {
          console.error(`Parse error UID ${msg.uid}:`, err);
        }
      }

      // Format recipient lists neatly
      const toAddresses = msg.envelope?.to?.map((t: any) => t.address).join(", ") ?? "";

      emails.push({
        uid: msg.uid,
        subject: msg.envelope?.subject ?? "(no subject)",
        to: toAddresses, // Useful for sent folder to see who you sent it to
        date: msg.internalDate,
        flags: msg.flags,
        body: {
          text: parsed?.text ?? "",
          html: parsed?.html ?? parsed?.textAsHtml ?? "",
        },
      });
    }

    // 9. Cleanup connection
    await client.logout();

    // 10. Response
    return NextResponse.json({
      mailbox: mailbox.email,
      folder: sentFolderName,
      count: emails.length,
      emails,
    });

  } catch (err) {
    console.error("EMAIL_SENT_RETRIEVE_ERROR:", err);

    return NextResponse.json(
      { error: "Failed to fetch sent emails" },
      { status: 500 }
    );
  }
}

import { prisma } from "@/lib/prisma";

export const runtime = "nodejs";

// Helper function to ping URLs with a short timeout
async function checkServiceStatus(url: string | null): Promise<"online" | "offline"> {
  if (!url) return "offline";
  
  // Normalize URLs (ensure absolute pathing for external or internal fetch)
  let targetUrl = url;
  if (url.startsWith("/")) {
    // If it's a relative local dashboard route, you can either assume it's up 
    // or point it back to your localhost port if you want a true server check:
    // e.g., targetUrl = `http://localhost:3000${url}`;
    return "online"; 
  }

  try {
    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), 2500); // 2.5-second timeout limit

    const response = await fetch(targetUrl, {
      method: "HEAD", // HEAD is much faster than GET since it drops the body payload
      signal: controller.signal,
      headers: { "User-Agent": "Dashboard-Status-Checker" },
    });

    clearTimeout(timeoutId);
    
    // Any typical success or redirection code means the app layer is alive
    return response.status >= 200 && response.status < 400 ? "online" : "offline";
  } catch (error) {
    return "offline";
  }
}

// GET all apps with dynamic live status checks
export async function GET(req: Request) {
  const { searchParams } = new URL(req.url);
  const label = searchParams.get("label") ?? undefined;
  const description = searchParams.get("description") ?? undefined;
  const url = searchParams.get("url") ?? undefined;

  // 1. Fetch apps from database
  const apps = await prisma.apps.findMany({
    where: {
      label,
      description,
      url,
    },
  });

  // 2. Ping all service URLs concurrently
  const appsWithStatus = await Promise.all(
    apps.map(async (app) => {
      const status = await checkServiceStatus(app.url);
      return {
        ...app,
        status, // Appends "online" or "offline" dynamically to the object
      };
    })
  );

  return Response.json(appsWithStatus);
}

export async function POST(request: Request) {
 
const token = process.env.PROXY_API_TOKEN;
  const endpoint = process.env.PROXY_SERVER_HOST_CREATE_ROUTE;

  if (!token) {
    return Response.json({ error: "Missing proxy token" }, { status: 500 });
  }

  if (!endpoint) {
    return Response.json({ error: "Missing proxy endpoint" }, { status: 500 });
  }

  try {
    const res = await fetch(endpoint, {
      headers: {
        "X-API-Key": token,
      },
      cache: "no-store",
    });

    if (!res.ok) {
      const details = await res.text();
      return Response.json(
        {
          error: "Proxy request failed",
          status: res.status,
          details,
        },
        { status: res.status }
      );
    }

    const data = await res.json();

    return Response.json(data);
  } catch (err) {
    const message = err instanceof Error ? err.message : "Failed to fetch";
    return Response.json({ error: message }, { status: 500 });
  }
}

import { NextResponse } from "next/server";
import { prisma } from "@/lib/prisma";

export async function POST(request: Request) {
  try {
    const usersWithoutStorage = await prisma.appUsers.findMany({
      where: {
        storage: {
          is: null,
        },
      },
      select: {
        id: true,
      },
    });

    if (usersWithoutStorage.length === 0) {
      return NextResponse.json(
        { message: "All existing users already have storage provisioned." },
        { status: 200 }
      );
    }

    const provisioningTasks = usersWithoutStorage.map((user) =>
      prisma.userStorage.create({
        data: {
          userId: user.id,
        },
      })
    );

    await prisma.$transaction(provisioningTasks);

    return NextResponse.json(
      {
        message: `Successfully provisioned storage for ${usersWithoutStorage.length} existing users.`,
        affectedUserIds: usersWithoutStorage.map((u) => u.id),
      },
      { status: 200 }
    );
  } catch (error) {
    console.error("Failed to provision existing users:", error);
    return NextResponse.json(
      { error: "Internal Server Error" },
      { status: 500 }
    );
  }
}

import { NextResponse } from "next/server";
import { prisma } from "@/lib/prisma";

export async function POST(request: Request) {
  try {
    const body = await request.json();
    const { name, description, userId } = body;

    // 1. Validation
    if (!name) {
      return NextResponse.json(
        { error: "Team name is required" },
        { status: 400 }
      );
    }

    // 2. Create the team and instantly connect the user
    const newTeam = await prisma.team.create({
      data: {
        name,
        description,
        // Because it's a many-to-many relation, we use 'connect' 
        // with an array of user identifier objects
        members: userId ? {
          connect: [{ id: userId }]
        } : undefined,
      },
      // Include members in the response payload to verify it worked
      include: {
        members: {
          select: {
            id: true,
            username: true,
            displayName: true,
          },
        },
      },
    });

    return NextResponse.json(newTeam, { status: 201 });

  } catch (error: any) {
    console.error("Failed to create team:", error);
    return NextResponse.json(
      { error: "Internal Server Error", details: error.message },
      { status: 500 }
    );
  }
}

import { prisma } from "@/lib/prisma";
import { NextResponse } from "next/server";
import { createClient } from "redis"; // Import the Redis client
import { resolveTicketingActor } from "@/lib/ticketing-auth";

// Setup a reusable redis publisher client
const redisUrl = process.env.REDIS_URL || "redis://172.20.0.25:6379";
const publisher = createClient({ url: redisUrl });

// Connect to Redis immediately on startup/invocation
publisher.connect().catch((err) => console.error("Redis Publisher Connection Error", err));

export async function POST(
  request: Request,
  { params }: { params: Promise<{ ticketId: string }> }
) {
  try {
    const actor = await resolveTicketingActor(request);

    if (!actor?.userId) {
      return NextResponse.json(
        { error: "Unauthorized" },
        { status: 401 }
      );
    }

    const { ticketId } = await params;
    const body = await request.json();
    const { text } = body;

    if (!text) {
      return NextResponse.json(
        { error: "Comment text is required" },
        { status: 400 }
      );
    }

    const newComment = await prisma.comment.create({
      data: {
        text,
        ticketId,
        authorId: actor.userId,
      },
      include: {
        author: {
          select: {
            id: true,
            username: true,
            displayName: true,
            avatarUrl: true,
          },
        },
      },
    });

    // 🔥 BROADCAST TO REDIS PUB/SUB
    // We convert the comment to a JSON string and publish it to a ticket-specific channel
    try {
      await publisher.publish(`ticket:${ticketId}:comments`, JSON.stringify(newComment));
    } catch (redisError) {
      console.error("Failed to publish real-time notification to Redis:", redisError);
      // We don't crash the request if Redis notifications temporarily fail
    }

    return NextResponse.json(newComment, { status: 201 });
  } catch (error: any) {
    console.error("Failed to add comment:", error);
    return NextResponse.json(
      { error: "Internal Server Error" },
      { status: 500 }
    );
  }
}

import { prisma } from "@/lib/prisma";
import { hashPassword } from "@/lib/password";
import { NextResponse } from "next/server";
import { DeleteObjectCommand } from "@aws-sdk/client-s3";
import { s3Client } from "@/lib/s3";
import { resolveTicketingActor } from "@/lib/ticketing-auth";

const BUCKET_NAME = process.env.S3_BUCKET!;

export const runtime = "nodejs";

function sanitizeAppUser(user: any) {
  if (!user) return user;
  
  const sanitized = { ...user };

  if (sanitized.storage) {
    sanitized.storage = {
      ...sanitized.storage,
      quotaBytes: Number(sanitized.storage.quotaBytes),
      usedBytes: Number(sanitized.storage.usedBytes),
    };
  }

  if (sanitized.files && Array.isArray(sanitized.files)) {
    sanitized.files = sanitized.files.map((file: any) => ({
      ...file,
      size: Number(file.size),
    }));
  }

  return sanitized;
}

const userSelectFields = {
  id: true,
  username: true,
  displayName: true,
  email: true,
  isActive: true,
  createdAt: true,
  updatedAt: true,
  isEntraUser: true,
  phone: true,
  mailboxes: { select: { id: true, email: true, isPrimary: true } },
  teams: { select: { id: true, name: true, description: true } },
  deviceTokens: { select: { id: true, platform: true, createdAt: true, deviceVersion: true, deviceName: true, deviceModelName: true, deviceBrand: true } },
  notifications: {
    select: {
      id: true,
      type: true,
      title: true,
      description: true,
      read: true,
      createdAt: true,
    },
  },
  githubLink: {
    
  },
  sessions: {
    select: {
      id: true,
      userAgent: true,
      ipAddress: true,
      signInUrl: true,
      createdAt: true,
      expiresAt: true,
      lastActive: true,
    },
  },
  storage: {
    select: {
      quotaBytes: true,
      usedBytes: true,
    },
  },
  files: {
    select: {
      id: true,
      owner: { select: { id: true, username: true } },
      bucket: true,
      objectKey: true,
      name: true,
      size: true,
    },
  },
  _count: { select: { createdTickets: true, assignedTickets: true } },
};

export async function GET(req: Request) {
  try {
    const actor = await resolveTicketingActor(req);

    if (!actor?.userId) {
      return Response.json({ error: "Unauthorized" }, { status: 401 });
    }

    // Check if the 'all' header is present
    const fetchAll = req.headers.get("all") !== null;

    if (fetchAll) {
      // Fetch all users using findMany
      const users = await prisma.appUsers.findMany({
        select: userSelectFields,
      });

      const sanitizedUsers = users.map(user => sanitizeAppUser(user));
      return Response.json(sanitizedUsers);
    } else {
      // Fetch the single authenticated user using our resolved token identity
      const user = await prisma.appUsers.findUnique({
        where: { id: actor.userId },
        select: userSelectFields,
      });

      if (!user) {
        return Response.json({ error: "User not found" }, { status: 404 });
      }

      return Response.json(sanitizeAppUser(user));
    }
  } catch (error) {
    console.error("GET user error:", error);
    return Response.json({ error: "Internal server error" }, { status: 500 });
  }
}

export async function POST(req: Request) {
  const body = await req.json();

  const username =
    typeof body.username === "string" ? body.username.trim().toLowerCase() : "";
  const password = typeof body.password === "string" ? body.password : "";
  const displayName =
    typeof body.displayName === "string" && body.displayName.trim()
      ? body.displayName.trim()
      : null;
  const email =
    typeof body.email === "string" && body.email.trim()
      ? body.email.trim().toLowerCase()
      : null;

  if (!username || !password) {
    return Response.json(
      { error: "username and password are required" },
      { status: 400 },
    );
  }

  const existingUser = await prisma.appUsers.findFirst({
    where: {
      OR: [{ username }, ...(email ? [{ email }] : [])],
    },
    select: {
      id: true,
    },
  });

  if (existingUser) {
    return Response.json(
      { error: "A user with that username or email already exists" },
      { status: 409 },
    );
  }

  const createdUser = await prisma.appUsers.create({
    data: {
      username,
      displayName,
      email,
      phone:
        typeof body.phone === "string" && body.phone.trim()
          ? body.phone.trim()
          : null,
      passwordHash: hashPassword(password),
      storage: {
        create: {},
      },
    },
    select: {
      id: true,
      username: true,
      displayName: true,
      email: true,
      phone: true,
      isActive: true,
      createdAt: true,
      updatedAt: true,
      storage: true,
    },
  });

  return Response.json(sanitizeAppUser(createdUser), { status: 201 });
}

export async function DELETE(req: Request) {
  try {
    const actor = await resolveTicketingActor(req);
    if (!actor?.userId) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }
    const userId = actor.userId;

    // Fetch all files belonging to the user
    const userFiles = await prisma.file.findMany({
      where: { ownerId: userId },
      select: { id: true, objectKey: true, size: true },
    });

    // Delete each file from S3
    for (const file of userFiles) {
      await s3Client.send(
        new DeleteObjectCommand({
          Bucket: BUCKET_NAME,
          Key: file.objectKey,
        })
      );
    }

    // Transaction: delete file records, reset storage, delete user
    await prisma.$transaction([
      prisma.file.deleteMany({ where: { ownerId: userId } }),
      prisma.userStorage.update({
        where: { userId },
        data: { usedBytes: 0 },
      }),
      prisma.appUsers.delete({ where: { id: userId } }),
    ]);

    return NextResponse.json({ success: true });
  } catch (error) {
    console.error("User deletion failed:", error);
    return NextResponse.json({ error: "Internal Server Error" }, { status: 500 });
  }
}

"use client";

import { useState } from "react";
import { useRouter } from "next/navigation";
import { ShieldCheck, ArrowLeft, Mail } from "lucide-react";

import { toast } from "sonner";
import { Button } from "@/components/ui/button";
import {
  Card,
  CardContent,
  CardDescription,
  CardFooter,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";

type Stage = "form" | "submitting" | "sent";

export default function ForgotPasswordPage() {
  const router = useRouter();
  const [stage, setStage] = useState<Stage>("form");
  const [email, setEmail] = useState("");

  async function handleSubmit() {
    if (!email.trim()) return;
    setStage("submitting");

    try {
      const res = await fetch("/api/auth/request-reset", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ email: email.trim().toLowerCase() }),
      });

      if (!res.ok) {
        const text = await res.text();
        throw new Error(text || `Server error (${res.status})`);
      }

      // Always show "sent" regardless of whether the email exists —
      // avoids leaking which addresses are registered.
      setStage("sent");
    } catch (err) {
      setStage("form");
      toast.error("Failed to send reset link", {
        description:
          err instanceof Error
            ? err.message
            : "Something went wrong. Please try again.",
      });
    }
  }

  // ── Shared card wrapper ──────────────────────────────────────────────────
  const wrap = (children: React.ReactNode) => (
    <Card className="w-full max-w-sm shadow-sm animate-in fade-in slide-in-from-bottom-2 duration-300">
      {children}
    </Card>
  );

  const page = (card: React.ReactNode) => (
    <div className="min-h-svh flex flex-col items-center justify-center px-4 py-12 bg-background">
      <div className="mb-8 flex flex-col items-center gap-2">
        <div className="flex items-center justify-center size-9 rounded-lg bg-foreground text-background">
          <ShieldCheck size={18} strokeWidth={2} />
        </div>
        <span className="text-sm font-semibold tracking-tight text-foreground">Fortmont</span>
      </div>
      {card}
      <p className="mt-8 text-[11px] text-muted-foreground">
        © {new Date().getFullYear()} Fortmont
      </p>
    </div>
  );

  // ── Form ─────────────────────────────────────────────────────────────────
  if (stage === "form" || stage === "submitting") return page(wrap(
    <>
      <CardHeader className="pb-4">
        <CardTitle className="text-lg">Reset your password</CardTitle>
        <CardDescription>
          Enter your account email and we'll send you a reset link.
        </CardDescription>
      </CardHeader>

      <CardContent className="space-y-4">
        <div className="space-y-1.5">
          <Label htmlFor="email">Email address</Label>
          <div className="relative">
            <Mail
              size={14}
              className="absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground pointer-events-none"
            />
            <Input
              id="email"
              type="email"
              placeholder="you@example.com"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              onKeyDown={(e) => e.key === "Enter" && handleSubmit()}
              autoComplete="email"
              autoFocus
              disabled={stage === "submitting"}
              className="pl-9"
            />
          </div>
        </div>
      </CardContent>

      <CardFooter className="flex-col gap-2">
        <Button
          className="w-full"
          onClick={handleSubmit}
          disabled={!email.trim() || stage === "submitting"}
        >
          {stage === "submitting" ? (
            <>
              <span
                className="mr-2 size-3.5 rounded-full border-2 border-background/40 border-t-background animate-spin"
              />
              Sending…
            </>
          ) : (
            "Send reset link"
          )}
        </Button>

        <Button
          variant="ghost"
          className="w-full text-muted-foreground"
          onClick={() => router.push("/login")}
          disabled={stage === "submitting"}
        >
          <ArrowLeft size={14} className="mr-2" />
          Back to login
        </Button>
      </CardFooter>
    </>
  ));

  // ── Sent ─────────────────────────────────────────────────────────────────
  if (stage === "sent") return page(wrap(
    <>
      <CardHeader className="items-center text-center pb-4">
        <div className="mb-3 flex size-16 items-center justify-center rounded-full border border-border bg-muted/40">
          <Mail size={24} className="text-foreground" />
        </div>
        <CardTitle className="text-lg">Check your inbox</CardTitle>
        <CardDescription>
          If <span className="font-medium text-foreground">{email}</span> is
          registered, a reset link is on its way. It expires in 60 minutes.
        </CardDescription>
      </CardHeader>

      <CardContent>
        <p className="text-xs text-muted-foreground text-center leading-relaxed">
          Didn't receive anything? Check your spam folder or contact your IT administrator.
        </p>
      </CardContent>

      <CardFooter className="flex-col gap-2">
        <Button
          variant="outline"
          className="w-full"
          onClick={() => {
            setEmail("");
            setStage("form");
          }}
        >
          Try a different email
        </Button>
        <Button
          variant="ghost"
          className="w-full text-muted-foreground"
          onClick={() => router.push("/login")}
        >
          <ArrowLeft size={14} className="mr-2" />
          Back to login
        </Button>
      </CardFooter>
    </>
  ));
}

